-- SOURCE scope_fix.sql sha256=217aaf22d37c87db733560108e50272680c62ebb48cc2762c2142a66dcf1ed89
CREATE OR REPLACE FUNCTION public.read_admin_student_directory(
    p_actor uuid,
    p_tenant uuid,
    p_search text,
    p_status text,
    p_program_id uuid,
    p_limit integer,
    p_offset integer
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE result jsonb;
BEGIN
    PERFORM public.assert_semester_registration_admin(p_actor,p_tenant,'students.read');
    IF p_limit<1 OR p_limit>100 OR p_offset<0 OR p_offset>1000000 THEN
        RAISE EXCEPTION 'Invalid directory page' USING ERRCODE='22023';
    END IF;
    IF p_status IS NOT NULL AND p_status NOT IN ('pending_sign_in','signed_in','no_signin') THEN
        RAISE EXCEPTION 'Invalid directory status' USING ERRCODE='22023';
    END IF;

    WITH profiles AS (
        SELECT s.student_id AS record_id,
            'student'::text AS record_type,
            coalesce(nullif(btrim(concat_ws(' ',u.first_name,u.last_name)),''),'Unknown student') AS student_name,
            coalesce(s.email,u.email) AS email,
            s.register_number,
            s.university_roll_number,
            CASE WHEN auth_user.last_sign_in_at IS NULL THEN 'no_signin' ELSE 'signed_in' END AS status,
            s.approval_status,
            u.status AS account_status,
            s.status AS student_status,
            s.is_active,
            auth_user.last_sign_in_at,
            NULL::text AS email_delivery_status,
            NULL::timestamptz AS expires_at,
            academic.program_id,
            academic.program_name,
            academic.program_code,
            academic.course_name,
            academic.branch_name,
            academic.branch_code,
            academic.batch_name,
            academic.batch_code,
            academic.section_name,
            academic.section_code,
            academic.admission_cohort_id,
            academic.academic_section_id,
            s.created_at
        FROM public.students s
        LEFT JOIN public.users u ON u.id=s.user_id
        LEFT JOIN auth.users auth_user ON auth_user.id=u.auth_user_id
        LEFT JOIN LATERAL (
            SELECT program.program_id,program.name AS program_name,program.code AS program_code,
                program.degree_type AS course_name,program.name AS branch_name,
                program.code AS branch_code,cohort.name AS batch_name,cohort.code AS batch_code,
                cohort.admission_cohort_id,
                section.name AS section_name,section.code AS section_code,
                section.academic_section_id
            FROM public.student_semester_registrations registration
            JOIN public.academic_sections section
                ON section.academic_section_id=registration.academic_section_id
                AND section.institution_id=p_tenant
            JOIN public.admission_cohorts cohort
                ON cohort.admission_cohort_id=section.admission_cohort_id
                AND cohort.institution_id=p_tenant
            JOIN public.programs program ON program.program_id=cohort.program_id
            JOIN public.departments department
                ON department.department_id=program.department_id
                AND department.institution_id=p_tenant
            JOIN public.semesters term ON term.semester_id=registration.semester_id
            JOIN public.academic_years academic_year
                ON academic_year.academic_year_id=term.academic_year_id
                AND academic_year.institution_id=p_tenant
            WHERE registration.student_id=s.student_id AND registration.institution_id=p_tenant
            ORDER BY term.start_date DESC,registration.assigned_at DESC,
                registration.semester_registration_id
            LIMIT 1
        ) academic ON true
        WHERE s.institution_id=p_tenant
    ), invitations AS (
        SELECT invitation.invitation_id AS record_id,'invitation'::text AS record_type,
            invitation.student_name,invitation.email,invitation.register_number,
            invitation.university_roll_number,
            CASE WHEN auth_user.last_sign_in_at IS NULL
                THEN 'pending_sign_in' ELSE 'signed_in' END AS status,
            NULL::text AS approval_status,NULL::text AS account_status,
            NULL::text AS student_status,NULL::boolean AS is_active,
            auth_user.last_sign_in_at,invitation.email_delivery_status,invitation.expires_at,
            program.program_id,program.name AS program_name,program.code AS program_code,
            program.degree_type AS course_name,program.name AS branch_name,
            program.code AS branch_code,cohort.name AS batch_name,cohort.code AS batch_code,
            cohort.admission_cohort_id,
            section.name AS section_name,section.code AS section_code,
            section.academic_section_id,invitation.created_at
        FROM public.student_onboarding_invitations invitation
        JOIN public.academic_sections section
            ON section.academic_section_id=invitation.academic_section_id
            AND section.institution_id=p_tenant
        JOIN public.admission_cohorts cohort
            ON cohort.admission_cohort_id=section.admission_cohort_id
            AND cohort.institution_id=p_tenant
        JOIN public.programs program ON program.program_id=cohort.program_id
        JOIN public.departments department
            ON department.department_id=program.department_id
            AND department.institution_id=p_tenant
        LEFT JOIN auth.users auth_user ON auth_user.id=invitation.provisioned_auth_user_id
        WHERE invitation.institution_id=p_tenant AND invitation.status='pending'
    ), directory AS (
        SELECT * FROM profiles UNION ALL SELECT * FROM invitations
    ), filtered AS (
        SELECT * FROM directory
        WHERE (nullif(btrim(coalesce(p_search,'')),'') IS NULL OR
            position(lower(btrim(p_search)) IN lower(concat_ws(' ',student_name,email,
                register_number,university_roll_number)))>0)
          AND (p_status IS NULL OR status=p_status)
          AND (p_program_id IS NULL OR program_id=p_program_id)
    ), program_options AS (
        SELECT DISTINCT program_id,program_name,program_code
        FROM directory WHERE program_id IS NOT NULL
    )
    SELECT jsonb_build_object(
        'items',coalesce((
            SELECT jsonb_agg(to_jsonb(page_row) ORDER BY page_row.created_at DESC,
                lower(page_row.student_name),page_row.record_id)
            FROM (
                SELECT * FROM filtered ORDER BY created_at DESC,lower(student_name),record_id
                LIMIT p_limit OFFSET p_offset
            ) page_row
        ),'[]'::jsonb),
        'total',(SELECT count(*) FROM filtered),
        'limit',p_limit,'offset',p_offset,
        'summary',(SELECT jsonb_build_object(
            'total',count(*),
            'pending_sign_in',count(*) FILTER (WHERE status='pending_sign_in'),
            'signed_in',count(*) FILTER (WHERE status='signed_in'),
            'no_signin',count(*) FILTER (WHERE status='no_signin')
        ) FROM directory),
        'programs',(SELECT coalesce(jsonb_agg(jsonb_build_object(
            'program_id',program_id,'program_name',program_name,'program_code',program_code
        ) ORDER BY lower(program_name),program_id),'[]'::jsonb) FROM program_options)
    ) INTO result;
    RETURN result;
END;
$$;
NOTIFY pgrst,'reload schema';

-- SOURCE profile_management.sql sha256=65fc947bbba07bf270d6a2a49844c25357ce1974d569c7cfcb7246194a1ce8b3
CREATE OR REPLACE FUNCTION public.update_admin_student_profile(
    p_actor uuid,p_tenant uuid,p_student uuid,p_student_name text,
    p_register_number text,p_university_roll_number text,p_section uuid
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE student_row record; before_row jsonb; v_section_id uuid;
    v_first_name text; v_last_name text;
BEGIN
    PERFORM public.assert_semester_registration_admin(p_actor,p_tenant,'students.update');
    IF p_section IS NOT NULL THEN
        PERFORM public.assert_semester_registration_admin(p_actor,p_tenant,'courses.manage');
    END IF;
    IF p_student_name IS NULL OR length(btrim(p_student_name)) NOT BETWEEN 1 AND 200
        OR p_register_number IS NULL OR length(btrim(p_register_number)) NOT BETWEEN 1 AND 128
        OR (p_university_roll_number IS NOT NULL
            AND length(btrim(p_university_roll_number)) NOT BETWEEN 1 AND 128) THEN
        RAISE EXCEPTION 'Invalid student identity' USING ERRCODE='22023';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('academic-setup:'||p_tenant::text,0));
    SELECT s.*,u.auth_user_id,u.first_name,u.last_name INTO student_row
    FROM public.students s JOIN public.users u ON u.id=s.user_id
    WHERE s.student_id=p_student AND s.institution_id=p_tenant
    FOR UPDATE OF s,u;
    IF NOT FOUND THEN RAISE EXCEPTION 'Student not found' USING ERRCODE='P0002'; END IF;

    IF EXISTS (
        SELECT 1 FROM public.students other
        WHERE other.institution_id=p_tenant AND other.student_id<>p_student
          AND (lower(btrim(other.register_number))=lower(btrim(p_register_number))
            OR lower(btrim(other.student_number))=lower(btrim(p_register_number))
            OR (p_university_roll_number IS NOT NULL
                AND lower(btrim(other.university_roll_number))=lower(btrim(p_university_roll_number))))
    ) THEN
        RAISE EXCEPTION 'Student identity already exists' USING ERRCODE='23505';
    END IF;
    SELECT registration.academic_section_id INTO v_section_id
    FROM public.student_semester_registrations registration
    JOIN public.semesters term ON term.semester_id=registration.semester_id
    WHERE registration.student_id=p_student AND registration.institution_id=p_tenant
    ORDER BY term.start_date DESC,registration.assigned_at DESC,
        registration.semester_registration_id
    LIMIT 1;
    IF p_section IS NOT NULL THEN
        PERFORM public.assign_student_semester(p_actor,p_tenant,p_student,p_section);
    END IF;

    before_row:=jsonb_build_object(
        'student_name',concat_ws(' ',student_row.first_name,student_row.last_name),
        'register_number',student_row.register_number,
        'university_roll_number',student_row.university_roll_number,
        'academic_section_id',v_section_id);
    v_first_name:=split_part(btrim(p_student_name),' ',1);
    v_last_name:=btrim(substr(btrim(p_student_name),length(v_first_name)+1));
    UPDATE public.users SET first_name=v_first_name,last_name=v_last_name,
        display_name=btrim(p_student_name),updated_at=now()
    WHERE id=student_row.user_id;
    UPDATE public.students SET student_number=btrim(p_register_number),
        register_number=btrim(p_register_number),
        university_roll_number=nullif(btrim(p_university_roll_number),''),
        updated_at=now()
    WHERE student_id=p_student AND institution_id=p_tenant;
    SELECT registration.academic_section_id INTO v_section_id
    FROM public.student_semester_registrations registration
    JOIN public.semesters term ON term.semester_id=registration.semester_id
    WHERE registration.student_id=p_student AND registration.institution_id=p_tenant
    ORDER BY term.start_date DESC,registration.assigned_at DESC,
        registration.semester_registration_id
    LIMIT 1;

    INSERT INTO public.admin_audit_log(actor_user_id,institution_id,action,table_name,record_id,record_data,status)
    VALUES(p_actor,p_tenant,'student.profile.updated','students',p_student::text,
        jsonb_build_object('before',before_row,'after',jsonb_build_object(
            'student_name',btrim(p_student_name),'register_number',btrim(p_register_number),
            'university_roll_number',nullif(btrim(p_university_roll_number),''),
            'academic_section_id',v_section_id)),
        'success');
    RETURN jsonb_build_object('student_id',p_student,'updated',true);
END;
$$;

CREATE FUNCTION public.set_admin_student_active(
    p_actor uuid,p_tenant uuid,p_student uuid,p_active boolean
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE student_row public.students;
BEGIN
    PERFORM public.assert_semester_registration_admin(p_actor,p_tenant,'students.update');
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('academic-setup:'||p_tenant::text,0));
    SELECT * INTO student_row FROM public.students
    WHERE student_id=p_student AND institution_id=p_tenant FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Student not found' USING ERRCODE='P0002'; END IF;
    IF p_active AND student_row.approval_status<>'approved' THEN
        RAISE EXCEPTION 'Only approved student accounts can be reactivated' USING ERRCODE='23514';
    END IF;
    IF student_row.status NOT IN ('active','inactive') THEN
        RAISE EXCEPTION 'Graduated or withdrawn student records cannot be reactivated here'
            USING ERRCODE='23514';
    END IF;
    IF student_row.is_active IS DISTINCT FROM p_active THEN
        UPDATE public.students SET is_active=p_active,
            status=CASE WHEN p_active THEN 'active' ELSE 'inactive' END,updated_at=now()
        WHERE student_id=p_student AND institution_id=p_tenant;
        INSERT INTO public.admin_audit_log(actor_user_id,institution_id,action,table_name,record_id,record_data,status)
        VALUES(p_actor,p_tenant,CASE WHEN p_active THEN 'student.activated' ELSE 'student.deactivated' END,
            'students',p_student::text,jsonb_build_object(
                'before',jsonb_build_object('status',student_row.status,'is_active',student_row.is_active),
                'after',jsonb_build_object('status',CASE WHEN p_active THEN 'active' ELSE 'inactive' END,
                    'is_active',p_active)),'success');
    END IF;
    RETURN jsonb_build_object('student_id',p_student,'is_active',p_active);
END;
$$;

-- SOURCE profile_deletion.sql sha256=25afacbc930441700144e4f3baa6300fca059f5c85b433c3d851c39c7043ce37
CREATE FUNCTION public.delete_unused_admin_student(
    p_actor uuid,p_tenant uuid,p_student uuid
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE student_row public.students; dependency record; linked boolean;
BEGIN
    PERFORM public.assert_semester_registration_admin(p_actor,p_tenant,'students.delete');
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('academic-setup:'||p_tenant::text,0));
    SELECT * INTO student_row FROM public.students
    WHERE student_id=p_student AND institution_id=p_tenant FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Student not found' USING ERRCODE='P0002'; END IF;

    FOR dependency IN
        SELECT child_schema.nspname AS schema_name,child_table.relname AS table_name,
            string_agg(format('child.%I=parent.%I',child_column.attname,parent_column.attname),
                ' AND ' ORDER BY keys.position) AS predicate
        FROM pg_catalog.pg_constraint fk
        JOIN pg_catalog.pg_class child_table ON child_table.oid=fk.conrelid
        JOIN pg_catalog.pg_namespace child_schema ON child_schema.oid=child_table.relnamespace
        CROSS JOIN LATERAL unnest(fk.conkey,fk.confkey)
            WITH ORDINALITY AS keys(child_number,parent_number,position)
        JOIN pg_catalog.pg_attribute child_column
            ON child_column.attrelid=fk.conrelid AND child_column.attnum=keys.child_number
        JOIN pg_catalog.pg_attribute parent_column
            ON parent_column.attrelid=fk.confrelid AND parent_column.attnum=keys.parent_number
        WHERE fk.contype='f' AND fk.confrelid=to_regclass('public.students')
        GROUP BY fk.oid,child_schema.nspname,child_table.relname
        ORDER BY child_schema.nspname,child_table.relname
    LOOP
        EXECUTE format(
            'SELECT EXISTS (SELECT 1 FROM %I.%I child JOIN public.students parent ON %s WHERE parent.student_id=$1)',
            dependency.schema_name,dependency.table_name,dependency.predicate)
        INTO linked USING p_student;
        IF linked THEN
            RAISE EXCEPTION 'Student has linked records' USING
                ERRCODE='P2003',DETAIL=dependency.table_name;
        END IF;
    END LOOP;

    INSERT INTO public.admin_audit_log(actor_user_id,institution_id,action,table_name,record_id,record_data,status)
    VALUES(p_actor,p_tenant,'student.profile.deleted','students',p_student::text,
        jsonb_build_object('before',jsonb_build_object(
            'student_id',p_student,'student_number',student_row.student_number,
            'register_number',student_row.register_number,
            'university_roll_number',student_row.university_roll_number,
            'user_id',student_row.user_id)),'success');
    DELETE FROM public.user_roles ur USING public.roles r
    WHERE ur.user_id=student_row.user_id AND ur.role_id=r.id AND r.name='student'
      AND ur.scope_type='institution' AND ur.scope_id=p_tenant;
    DELETE FROM public.students WHERE student_id=p_student AND institution_id=p_tenant;
    UPDATE public.users SET status='inactive',updated_at=now()
    WHERE id=student_row.user_id
      AND NOT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id=student_row.user_id);
    RETURN jsonb_build_object('student_id',p_student,'deleted',true);
END;
$$;

-- SOURCE profile_management_security.sql sha256=25d80afa5e8c8b7cb983126458afbd823d92cdc5b373c6cf300143fe7dbf6028
REVOKE ALL ON FUNCTION public.update_admin_student_profile(uuid,uuid,uuid,text,text,text,uuid),
    public.set_admin_student_active(uuid,uuid,uuid,boolean),
    public.delete_unused_admin_student(uuid,uuid,uuid)
    FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.update_admin_student_profile(uuid,uuid,uuid,text,text,text,uuid),
    public.set_admin_student_active(uuid,uuid,uuid,boolean),
    public.delete_unused_admin_student(uuid,uuid,uuid)
    TO service_role;
NOTIFY pgrst,'reload schema';
COMMIT;
